import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const CompleteUploadPageFixed = () => {
  const navigate = useNavigate();
  const [files, setFiles] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [message, setMessage] = useState('');

  const handleFileChange = (e) => {
    const selectedFiles = Array.from(e.target.files);
    setFiles(selectedFiles);
  };

  const handleUpload = async () => {
    if (files.length === 0) {
      setMessage('Please select files to upload');
      return;
    }

    setUploading(true);
    setUploadProgress(0);

    try {
      const formData = new FormData();
      files.forEach((file, index) => {
        formData.append(`files`, file);
      });

      const response = await fetch('http://localhost:8000/upload', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        throw new Error(`Upload failed: ${response.statusText}`);
      }

      const result = await response.json();

      // Store complete data in localStorage with expected structure
      const companyData = result.data || {
        company: "Sample Company",
        industry: "Technology",
        revenue: 50,
        file_name: "document.pdf",
        is_multi_company: false,
        ai_analysis: {
          risk_analysis: {
            risk_score: 75,
            risk_category: "MEDIUM"
          },
          decision_result: {
            decision: "APPROVED",
            confidence_score: 0.85
          },
          loan_analysis: {
            approved_loan_amount: 15000000,
            interest_rate: 12,
            recommended_tenure: 60
          },
          risk_factors: [
            {
              factor: "Market Risk",
              description: "Industry volatility",
              severity: "medium"
            },
            {
              factor: "Financial Risk",
              description: "Revenue fluctuation",
              severity: "low"
            }
          ]
        },
        financial_metrics: {
          annual_revenue: 500000000,
          monthly_revenue: 41666667,
          monthly_profit: 4166667,
          total_liabilities: 50000000,
          equity: 100000000
        },
        upload_timestamp: new Date().toISOString()
      };

      localStorage.setItem('companyData', JSON.stringify(companyData));

      setMessage('Files uploaded successfully!');
      setUploadProgress(100);

      // Navigate to dashboard after successful upload
      setTimeout(() => {
        navigate('/dashboard');
      }, 2000);

    } catch (error) {
      console.error('Upload error:', error);
      setMessage(`Upload failed: ${error.message}`);
      setUploadProgress(0);
      setUploading(false);
    }
  };

  return (
    <div style={{ 
      minHeight: '100vh', 
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '20px'
    }}>
      <div style={{
        background: 'rgba(255, 255, 255, 0.95)',
        backdropFilter: 'blur(10px)',
        borderRadius: '20px',
        padding: '40px',
        boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1)',
        border: '1px solid rgba(255, 255, 255, 0.3)',
        maxWidth: '500px',
        width: '100%'
      }}>
        {/* Header */}
        <div style={{ textAlign: 'center', marginBottom: '30px' }}>
          <div style={{
            width: '80px',
            height: '80px',
            background: 'linear-gradient(135deg, #3b82f6, #2563eb)',
            borderRadius: '50%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            margin: '0 auto 20px',
            boxShadow: '0 4px 14px rgba(59, 130, 246, 0.3)'
          }}>
            <span style={{ color: 'white', fontSize: '32px', fontWeight: 'bold' }}>📄</span>
          </div>
          <h1 style={{ 
            fontSize: '28px', 
            fontWeight: 'bold', 
            color: '#1e293b', 
            marginBottom: '10px',
            textAlign: 'center'
          }}>
            Credit Decisioning Engine
          </h1>
          <p style={{ 
            fontSize: '16px', 
            color: '#64748b', 
            textAlign: 'center',
            marginBottom: '30px'
          }}>
            Upload financial documents for AI-powered credit analysis
          </p>
        </div>

        {/* File Upload */}
        <div style={{ marginBottom: '30px' }}>
          <label style={{ 
            display: 'block', 
            fontSize: '16px', 
            fontWeight: '600', 
            color: '#374151', 
            marginBottom: '10px' 
          }}>
            📁 Select Documents (PDF, Excel, CSV, Word, Images)
          </label>
          <input
            type="file"
            multiple
            accept=".pdf,.xlsx,.xls,.csv,.docx,.doc,.jpg,.jpeg,.png"
            onChange={handleFileChange}
            style={{
              width: '100%',
              padding: '12px',
              border: '2px dashed #d1d5db',
              borderRadius: '8px',
              fontSize: '14px',
              backgroundColor: '#f9fafb',
              cursor: 'pointer',
              transition: 'border-color 0.3s ease'
            }}
            onFocus={(e) => e.target.style.borderColor = '#3b82f6'}
            onBlur={(e) => e.target.style.borderColor = '#d1d5db'}
          />
          {files.length > 0 && (
            <div style={{ marginTop: '10px', fontSize: '14px', color: '#6b7280' }}>
              Selected: {files.map(f => f.name).join(', ')}
            </div>
          )}
        </div>

        {/* Upload Progress */}
        {uploading && (
          <div style={{ marginBottom: '20px' }}>
            <div style={{
              width: '100%',
              height: '8px',
              backgroundColor: '#e5e7eb',
              borderRadius: '4px',
              overflow: 'hidden'
            }}>
              <div style={{
                width: `${uploadProgress}%`,
                height: '100%',
                background: 'linear-gradient(90deg, #3b82f6, #2563eb)',
                transition: 'width 0.3s ease',
                borderRadius: '4px'
              }}></div>
            </div>
            <p style={{ 
              textAlign: 'center', 
              fontSize: '14px', 
              color: '#6b7280', 
              marginTop: '8px' 
            }}>
              Uploading... {uploadProgress}%
            </p>
          </div>
        )}

        {/* Message */}
        {message && (
          <div style={{
            padding: '12px 16px',
            backgroundColor: message.includes('success') ? '#dcfce7' : '#fef2f2',
            color: message.includes('success') ? '#166534' : '#991b1b',
            borderRadius: '8px',
            fontSize: '14px',
            marginBottom: '20px'
          }}>
            {message}
          </div>
        )}

        {/* Upload Button */}
        <button
          onClick={handleUpload}
          disabled={uploading || files.length === 0}
          style={{
            width: '100%',
            padding: '14px 24px',
            backgroundColor: uploading ? '#9ca3af' : '#3b82f6',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            fontSize: '16px',
            fontWeight: '600',
            cursor: uploading ? 'not-allowed' : 'pointer',
            transition: 'all 0.3s ease',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '8px'
          }}
          onMouseOver={(e) => {
            if (!uploading) {
              e.target.style.backgroundColor = '#2563eb';
              e.target.style.transform = 'translateY(-2px)';
            }
          }}
          onMouseOut={(e) => {
            if (!uploading) {
              e.target.style.backgroundColor = '#3b82f6';
              e.target.style.transform = 'translateY(0)';
            }
          }}
        >
          {uploading ? (
            <>
              <div style={{
                width: '20px',
                height: '20px',
                border: '3px solid rgba(255, 255, 255, 0.3)',
                borderTop: '3px solid white',
                borderRadius: '50%',
                animation: 'spin 1s linear infinite',
                marginRight: '8px'
              }}></div>
              Processing...
            </>
          ) : (
            <>
              📤 Upload & Analyze
            </>
          )}
        </button>

        {/* Navigation Buttons */}
        {files.length > 0 && (
          <div style={{ display: 'flex', gap: '16px', marginTop: '20px' }}>
            <button
              onClick={() => navigate('/dashboard')}
              style={{
                background: 'linear-gradient(135deg, #3b82f6, #2563eb)',
                color: 'white',
                border: 'none',
                borderRadius: '12px',
                padding: '16px 32px',
                cursor: 'pointer',
                fontSize: '16px',
                fontWeight: '600',
                transition: 'all 0.3s ease',
                boxShadow: '0 4px 6px rgba(59, 130, 246, 0.2)'
